optimization-trial.patch:
diff --git a/tools/bot-evaluation/src/execution.rs b/tools/bot-evaluation/src/execution.rs
index addd6ea5..d87a5b9c 100644
--- a/tools/bot-evaluation/src/execution.rs
+++ b/tools/bot-evaluation/src/execution.rs
@@ -71,7 +71,7 @@ pub(crate) fn play(
             .min(wall)
             .saturating_duration_since(Instant::now())
             .min(Duration::from_millis(100));
-        let frame = match host.receive(wait) {
+        let mut frame = match host.receive(wait) {
             Ok(v) => v,
             Err(e) => {
                 if e.to_string().contains("timed out") {
@@ -98,7 +98,7 @@ pub(crate) fn play(
         match frame["type"].as_str().unwrap_or("") {
             "handle_created" => cleanup["handles_created"] = json!(1),
             "initial" => {
-                records[mapped]["initial"] = frame["initial"].clone();
+                records[mapped]["initial"] = frame["initial"].take();
                 map_players(&mut records[mapped]["initial"], swapped);
             }
             "event" | "decision" => {
@@ -112,10 +112,10 @@ pub(crate) fn play(
                     host_dead = true;
                     break;
                 }
-                let mut entry = frame["entry"].clone();
+                let mut entry = frame["entry"].take();
                 if frame["type"] == "decision" {
                     // Reuse the pre-invocation checkpoint in engine-seat coordinates.
-                    entry["prompt"] = checkpoint["pending_prompt"].clone();
+                    entry["prompt"] = checkpoint["pending_prompt"].take();
                 }
                 map_players(&mut entry, swapped);
                 if frame["type"] == "decision" {
@@ -140,7 +140,7 @@ pub(crate) fn play(
                 checkpoint["pending_prompt"] = frame["prompt"].clone();
                 checkpoint["player"] = json!(if mapped == 0 { "a" } else { "b" });
             }
-            "attempted_response" => checkpoint["attempted_response"] = frame["response"].clone(),
+            "attempted_response" => checkpoint["attempted_response"] = frame["response"].take(),
             "failure" => {
                 failure = Some(frame["failure"].clone());
                 terminal = Some(frame);
